#!/usr/bin/env node
'use strict';

/**
 * test-obfuscator-io-real-corpus.js
 *
 * Coverage test against REAL obfuscator.io output, generated by the actual
 * javascript-obfuscator 5.8.1 engine (see the fixture README for provenance).
 *
 * ── Why this exists ──────────────────────────────────────────────────────
 * AGENTS.md known-work #1 said the RC4 decode path was "exercised by the test
 * fixture" but never validated end-to-end on real output. That is now closed —
 * and doing it surfaced two things that were not previously known:
 *
 *  1. The decoder is CORRECT on the ordinary matrix. 15 of 16 real samples
 *     (plain / base64 / rc4 / mixed / shuffle / wrappers / CFF / compact /
 *     callsTransform / splitStrings / VM) recover the original plaintext.
 *
 *  2. With `selfDefending` + `debugProtection` the string-array rotation
 *     offset is sometimes resolved incorrectly and the decoder emits WRONG
 *     strings — plausible-looking, but not what the original said. This test
 *     pins the known-good behaviour and asserts the anti-debug detection, and
 *     deliberately does NOT assert full recovery on the affected sample, since
 *     that is known-work #12 rather than a regression.
 *
 * The anti-debug assertions exist because the Jscrambler-only signature matched
 * ZERO real obfuscator.io samples, so `expectAntiDebugging` was false on code
 * that demonstrably has it.
 */

const path = require('path');
const fs = require('fs');
const os = require('os');
const { spawnSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const CORPUS = path.join(__dirname, 'fixtures', 'obfuscator-io-real');
const OMEGA = path.join(ROOT, 'bin', 'omega.js');

let pass = 0, fail = 0;
const failures = [];
function ok(name, cond, detail) {
  if (cond) pass++;
  else { fail++; failures.push(name + (detail ? `  — ${detail}` : '')); }
}

console.log('\n── Real obfuscator.io corpus coverage ──');

if (!fs.existsSync(CORPUS)) {
  console.log('  corpus missing — nothing to assert');
  process.exit(0);
}

function scan(name) {
  const file = path.join(CORPUS, name);
  const out = fs.mkdtempSync(path.join(os.tmpdir(), 'obfio-real-'));
  const r = spawnSync(process.execPath,
    [OMEGA, file, '--all', '--report', '--no-color', '--out', out],
    { encoding: 'utf8', timeout: 300000, maxBuffer: 128 * 1024 * 1024 });
  let report = null, decoded = '';
  try { report = JSON.parse(fs.readFileSync(path.join(out, 'report.json'), 'utf8')); } catch (_) {}
  const art = path.join(out, `${name.replace(/\.js$/, '')}.decoded.js`);
  if (fs.existsSync(art)) decoded = fs.readFileSync(art, 'utf8');
  try { fs.rmSync(out, { recursive: true, force: true }); } catch (_) {}
  return { status: r.status, report, decoded, stderr: r.stderr || '' };
}

// Strings that MUST reappear in the decoded output if decoding worked.
const MARKERS = [
  'Content-Type', 'application/json', 'Bearer', 'getElementById',
  'appendChild', 'lastRender', 'metrics', 'XMLHttpRequest',
];

// Samples whose recovery is expected to be complete.
const CLEAN = [
  '01-plain.js', '02-base64.js', '03-rc4.js', '04-rc4-mixed.js',
  '05-rc4-shuffle.js', '06-rc4-wrappers-fn.js', '07-rc4-wrappers-var.js',
  '08-rc4-cff.js', '09-rc4-mangled.js', '12-rc4-compact.js',
  '13-calls-transform.js', '14-splitStrings.js', '15-vm.js',
];

// Known-imperfect (known-work #12): selfDefending/debugProtection breaks the
// rotation offset for some seeds. Detection only — no recovery assertion.
const ANTIDEBUG = ['11-rc4-full.js'];

for (const name of CLEAN) {
  const r = scan(name);
  if (!r.report) { ok(`${name}: produces a report`, false, `exit ${r.status}`); continue; }
  const fp = (r.report.obfuscatorFingerprint || {}).primary || {};
  ok(`${name}: identified as obfuscator.io`, fp.obfuscator === 'obfuscator.io',
     `got ${fp.obfuscator}`);
  const hit = MARKERS.filter(m => r.decoded.includes(m));
  ok(`${name}: decodes plaintext (${hit.length}/${MARKERS.length})`, hit.length >= 7,
     `missing: ${MARKERS.filter(m => !r.decoded.includes(m)).join(', ')}`);
}

// ── anti-debug detection on the selfDefending/debugProtection sample ──────
for (const name of ANTIDEBUG) {
  const r = scan(name);
  if (!r.report) { ok(`${name}: produces a report`, false, `exit ${r.status}`); continue; }
  const hints = (r.report.obfuscatorFingerprint || {}).llmHints || {};
  ok(`${name}: expectAntiDebugging is true`, hints.expectAntiDebugging === true,
     'the Jscrambler-only signature did not match real obfuscator.io output');
}

// ── and correctly NOT set on the ordinary matrix ──────────────────────────
for (const name of ['01-plain.js', '03-rc4.js', '08-rc4-cff.js']) {
  const r = scan(name);
  if (!r.report) continue;
  const hints = (r.report.obfuscatorFingerprint || {}).llmHints || {};
  ok(`${name}: expectAntiDebugging is false (no anti-debug in source)`,
     hints.expectAntiDebugging !== true);
}

// ── the unobfuscated source must not be mislabelled ──────────────────────
{
  const r = scan('00-original-plain.js');
  if (r.report) {
    const fp = (r.report.obfuscatorFingerprint || {}).primary || {};
    ok('00-original-plain.js: NOT labelled obfuscator.io', fp.obfuscator !== 'obfuscator.io',
       `got ${fp.obfuscator} — false positive on clean source`);
  }
}

console.log('\n' + '═'.repeat(62));
console.log(`  PASSED: ${pass}`);
if (fail) {
  console.log(`  FAILED: ${fail}`);
  console.log('\n  Failure detail:');
  for (const f of failures) console.log(`    ✗ ${f}`);
}
process.exit(fail === 0 ? 0 : 1);
